import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

export default function Landing() {
  const navigate = useNavigate();
  const [scrolled, setScrolled] = useState(false);
  const [topProfs, setTopProfs] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    
    api.get('/api/professeurs/')
      .then(res => {
        // Sécurité : on s'assure que res.data est un tableau
        const data = Array.isArray(res.data) ? res.data : [];
        const valid = data.filter(p => p && p.statut_validation === 'validé').slice(0, 4);
        setTopProfs(valid);
      })
      .catch(err => console.error("Erreur API:", err));

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="min-h-screen bg-white text-[#1a1a1a]" style={{ fontFamily: 'sans-serif' }}>
      
      {/* --- NAVBAR --- */}
      <nav className={`fixed w-full z-50 transition-all duration-500 px-6 md:px-12 ${scrolled ? 'bg-white py-4 border-b border-gray-100 shadow-sm' : 'bg-transparent py-8'}`}>
        <div className="max-w-[1800px] mx-auto flex justify-between items-center">
          <div className="flex items-center gap-12">
            <h1 className="text-xl font-bold tracking-[0.3em] uppercase cursor-pointer" onClick={() => window.scrollTo(0,0)}>
              EduMatch
            </h1>
            <div className="hidden lg:flex gap-8 text-[10px] uppercase tracking-[0.2em] font-medium">
              <span onClick={() => navigate('/profs')} className="cursor-pointer hover:opacity-50">Formateurs</span>
              <span className="cursor-pointer hover:opacity-50">À propos</span>
            </div>
          </div>
          <div className="flex items-center gap-6 text-[10px] uppercase tracking-[0.2em]">
            <button onClick={() => navigate('/login')}>Connexion</button>
            <button onClick={() => navigate('/register')} className="font-bold border border-black px-4 py-2">S'inscrire</button>
          </div>
        </div>
      </nav>

      {/* --- HERO SECTION --- */}
      <section className="h-screen flex flex-col items-center justify-center bg-[#f9f9f9] text-center px-4">
        <span className="text-[10px] uppercase tracking-[0.5em] text-gray-400 mb-8">
          L'excellence académique
        </span>
        <h2 className="text-5xl md:text-8xl font-light tracking-tighter leading-none mb-12">
          Apprenez sans <br />
          <span style={{ fontStyle: 'italic' }}>compromis.</span>
        </h2>
        <form 
          onSubmit={(e) => { e.preventDefault(); navigate(`/profs?q=${search}`); }}
          className="flex w-full max-w-xl border-b border-black py-2"
        >
          <input 
            type="text" 
            placeholder="RECHERCHER UNE MATIÈRE..." 
            className="bg-transparent w-full text-sm uppercase tracking-widest outline-none"
            onChange={(e) => setSearch(e.target.value)}
          />
          <button type="submit" className="font-bold px-4">→</button>
        </form>
      </section>

      {/* --- MENTORS SECTION --- */}
      <section className="py-32 px-6 md:px-12 max-w-[1600px] mx-auto">
        <div className="flex justify-between items-end mb-16 border-b border-gray-100 pb-8">
          <h2 className="text-2xl font-light uppercase tracking-widest">Nos Mentors</h2>
          <button onClick={() => navigate('/profs')} className="text-[10px] uppercase tracking-widest border-b border-black pb-1">Voir tout</button>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12">
          {topProfs.length > 0 ? topProfs.map((p, i) => (
            <div key={i} className="cursor-pointer group" onClick={() => navigate('/login')}>
              <div className="aspect-[3/4] bg-gray-100 mb-6 overflow-hidden">
                <img 
                  src={p.photo_url ? `http://localhost:8001${p.photo_url}` : "https://via.placeholder.com/600x800"} 
                  className="w-full h-full object-cover grayscale transition-all duration-700 group-hover:grayscale-0" 
                  alt="" 
                />
              </div>
              {/* Sécurité : on force l'affichage en string avec String() */}
              <h4 className="text-[11px] uppercase tracking-widest font-bold">
                {String(p.user_prenom || '')} {String(p.user_nom || '')}
              </h4>
              <p className="text-[10px] text-gray-400 uppercase mt-1 tracking-widest">
                {p.tarifs_matieres?.[0]?.nom_matiere ? String(p.tarifs_matieres[0].nom_matiere) : 'Enseignant'}
              </p>
            </div>
          )) : (
            <p className="text-[10px] uppercase tracking-widest text-gray-400">Chargement des mentors...</p>
          )}
        </div>
      </section>

      {/* --- FOOTER --- */}
      <footer className="py-20 px-6 border-t border-gray-100 text-center md:text-left">
        <div className="max-w-[1600px] mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div>
            <h2 className="text-sm tracking-[0.4em] uppercase font-bold">EduMatch</h2>
            <p className="text-[9px] text-gray-400 uppercase tracking-widest mt-2">Tunisia Project PFE</p>
          </div>
          <p className="text-[8px] text-gray-300 uppercase tracking-[0.4em]">
            © {new Date().getFullYear()} EDUMATCH - ALL RIGHTS RESERVED
          </p>
        </div>
      </footer>

    </div>
  );
}
